def compute_normals(verts, faces):
    normals = np.zeros_like(verts, dtype=np.float32)
    v0 = verts[faces[:,0]]; v1 = verts[faces[:,1]]; v2 = verts[faces[:,2]]
    fn = np.cross(v1-v0, v2-v0)
    fn_len = np.linalg.norm(fn, axis=1, keepdims=True)+1e-8
    fn /= fn_len
    np.add.at(normals, faces[:,0], fn)
    np.add.at(normals, faces[:,1], fn)
    np.add.at(normals, faces[:,2], fn)
    normals /= (np.linalg.norm(normals, axis=1, keepdims=True)+1e-8)
    return normals

def gen_verts(identity, expression, rotations, translation):
    v = gnm(np.array(identity,dtype=np.float32), np.array(expression,dtype=np.float32), np.array(rotations,dtype=np.float32).reshape(num_joints,3), np.array(translation,dtype=np.float32)).astype(np.float32)
    if np.isnan(v).any():
        print("[ERROR] NaN in verts!")
        return template_verts
    return v

def get_bounds(verts):
    bmin = verts.min(axis=0); bmax = verts.max(axis=0)
    center = (bmin+bmax)*0.5
    size = bmax-bmin
    diag = float(np.linalg.norm(size))
    return bmin, bmax, center, size, diag

def facs_to_expr(name, intensity=1.0):
    """Legacy wrapper - returns only expression for backward compat"""
    expr, _, _ = facs_to_full_params(name, intensity)
    return expr

def get_region_mask(region):
    """Return boolean mask for expression dims: left_eye 0-99, right_eye 100-199, lower_face 200-349, tongue 350-381, iris 382"""
    mask = np.zeros(expression_dim, dtype=bool)
    if region == "left_eye":
        mask[0:100] = True
    elif region == "right_eye":
        mask[100:200] = True
    elif region == "lower_face":
        mask[200:350] = True
    elif region == "tongue":
        mask[350:382] = True
    elif region == "iris":
        mask[382:383] = True
    elif region == "eyes":  # both eyes
        mask[0:200] = True
    elif region == "all":
        mask[:] = True
    elif region == "mouth":  # same as lower_face for now
        mask[200:350] = True
    return mask

