class Camera:
    def __init__(self, verts):
        bmin, bmax, center, size, diag = get_bounds(verts)
        self.center = center
        self.target = center.copy()
        self.distance = max(diag*2.0, float(size.max())*3.0, 0.8)
        self.yaw=90.0; self.pitch=10.0; self.fov=35.0
        self.near=0.1; self.far=100.0
        print(f"[Camera] center {self.target} size {size} diag {diag:.4f} dist {self.distance:.4f} near {self.near} far {self.far}")
    def eye(self):
        yaw=math.radians(self.yaw); pitch=math.radians(self.pitch)
        x=self.distance*math.cos(pitch)*math.cos(yaw)
        y=self.distance*math.sin(pitch)
        z=self.distance*math.cos(pitch)*math.sin(yaw)
        return self.target+np.array([x,y,z],dtype=np.float32)
    def forward(self):
        f = self.target - self.eye()
        return f / (np.linalg.norm(f)+1e-8)
    def view(self): return look_at(self.eye(), self.target, np.array([0,1,0],dtype=np.float32))
    def proj(self, aspect): return persp(math.radians(self.fov), aspect, self.near, self.far)
    def focus(self, verts):
        bmin, bmax, center, size, diag = get_bounds(verts)
        self.target = center
        self.distance = max(diag*2.0, float(size.max())*3.0, 0.8)
        print(f"[Focus] target {self.target} dist {self.distance}")

def log_debug_info(cam, verts, model, view, proj, log_file=None):
    bmin, bmax, center, size, diag = get_bounds(verts)
    eye = cam.eye(); fwd = cam.forward()
    to_center = center - eye
    dist_to_center = float(np.linalg.norm(to_center))
    dot_fwd = float(np.dot(fwd, to_center) / (np.linalg.norm(to_center)+1e-8))
    frustum = frustum_check(verts, model, view, proj)
    mvp = proj.T @ view.T @ model.T
    lines = []
    lines.append(f"\n========== DEBUG {datetime.datetime.now()} ==========")
    lines.append(f"Camera Eye {eye} Target {cam.target} Dist {cam.distance:.4f} Yaw {cam.yaw:.1f} Pitch {cam.pitch:.1f} FOV {cam.fov}")
    lines.append(f"  Forward {fwd} Dot to center {dot_fwd:.3f}")
    lines.append(f"Head Bounds min {bmin} max {bmax} center {center} size {size} diag {diag:.4f} mean {frustum['mean']}")
    lines.append(f"  Center NDC {frustum['center_ndc']} corners inside {frustum['num_inside']}/8")
    lines.append(f"  HEAD IN FRUSTUM? {frustum['num_inside']>0 or (np.abs(frustum['center_ndc'])<=1).all() and frustum['center_clip'][3]>0}")
    if frustum['is_center_behind']:
        lines.append(f"  *** BEHIND CAMERA ***")
    text = "\n".join(lines)
    print(text)
    if log_file:
        with open(log_file, 'a') as f: f.write(text+"\n")
    return text, frustum

